import{z as i,x as r,o as l,c as s,q as n,j as p,D as P,d as e,s as o,S as t,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"购买力平价与一价定律","description":"","frontmatter":{"title":"购买力平价与一价定律","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ppp-loop.md","filePath":"econ/ppp-loop.md","lastUpdated":1791413859000}'),A={name:"econ/ppp-loop.md"};function d(C,E,F,m,D,u){const B=r("Mermaid");return l(),s("div",null,[E[2]||(E[2]=n('<h1 id="购买力平价与一价定律" tabindex="-1">购买力平价与一价定律 <a class="header-anchor" href="#购买力平价与一价定律" aria-label="Permalink to &quot;购买力平价与一价定律&quot;">​</a></h1><div class="epigraph"><p>一价定律说可贸易同质货物在扣除壁垒后不应有两套价格；购买力平价把这句话升到价格指数，于是名义汇率要对齐两国的 $P$。</p><footer>—— Cassel 的购买力平价；对照 Friedman 对浮动汇率与相对通胀的论述</footer></div><p><a href="/econ/twin-deficits">上一课</a>（双赤字）。在此之上， \\(CA\\) 写成 \\(S-I\\)。那是数量账户，还没有两国价格如何换算。本课的缺口是：汇率作为两国货币的相对价格，如何与已经学过的 \\(P\\) 对齐。一价定律是货物层；PPP 是指数层。蒙代尔–弗莱明用短期粘性价格与资本流动，长期仍要回到某种 PPP 或利率平价；本课只钉物价锚。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>对可贸易的同质商品，无套利要求</p> \\[P_i = E\\cdot P_i^*, \\]<p>\\(E\\) 为名义汇率（本币/外币），忽略运费与关税时即一价定律。对价格指数，绝对 PPP 写 \\(P=E P^*\\)；相对 PPP 写 \\(\\Delta\\ln E \\approx \\pi-\\pi^*\\)。数量论在两国同时成立时，相对通胀差应对齐货币增长差，从而对齐 \\(\\Delta\\ln E\\)——Friedman 把浮动汇率读成让各国选择自己的 \\(\\pi\\)，汇率去吸收，而不是用汇率去「创造」实际 \\(CA\\)。</p><p>缺口不是重讲指数：篮子不同，PPP 必有偏差。可贸易与不可贸易（Balassa–Samuelson）使实际汇率 \\(q=E P^*/P\\) 可以长期偏离 1。本课允许 \\(q\\) 慢变，仍把 PPP 当长期名义锚的参照，不是每季的交易策略。</p><p><span class="marginnote">数字实例：相对 PPP 说贬值率对齐通胀差。本国通胀 5%、外国通胀 2%，本币预期每年贬值约 \\(5\\%-2\\%=3\\%\\)。粗略换算：持有外币资产的额外收益若跑不赢这 3 个点的贬值，换汇并不占便宜——通胀差就是汇率的方向盘。</span></p><p><span class="marginnote">实际汇率上升（按本定义）表示本国货物相对变便宜。\\(CA\\) 是否改善取决于吸收与支出转换，不是 PPP 偏差的符号单独决定。量化栏的 CIP 是有抛补的利率平价，对象是资产，不是 CPI 篮子。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>绝对 PPP 用同一篮子的国际价格比较；ICP、宾大世界表一类是发展核算里比较 \\(y\\) 水平的工具，已在<a href="/econ/convergence-accounting">收敛核算</a>用过购买力，这里接到汇率。相对 PPP 更适合通胀差：若 \\(q\\) 均值复归，则 \\(\\pi-\\pi^*\\) 主导 \\(\\Delta\\ln E\\)。</p>',12)),(l(),p(t,null,{default:P(()=>[o(B,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20LOOP%5B%22%E4%B8%80%E4%BB%B7%EF%BC%9A%E5%8F%AF%E8%B4%B8%E6%98%93%E5%90%8C%E8%B4%A8%E5%93%81%22%5D%20--%3E%20PPP%5B%22%E6%8C%87%E6%95%B0%E5%B1%82%20PPP%22%5D%0A%20%20PPP%20--%3E%20REL%5B%22%E7%9B%B8%E5%AF%B9%20PPP%EF%BC%9A%CE%94e%20%E2%89%88%20%CF%80%E2%88%92%CF%80*%22%5D%0A%20%20QTM%5B%22%E4%B8%A4%E5%9B%BD%E6%95%B0%E9%87%8F%E8%AE%BA%22%5D%20--%3E%20REL%0A%20%20NT%5B%22%E4%B8%8D%E5%8F%AF%E8%B4%B8%E6%98%93%20%2F%20%E7%AF%AE%E5%AD%90%22%5D%20--%3E%20Q%5B%22%E5%AE%9E%E9%99%85%E6%B1%87%E7%8E%87%20q%20%E5%8F%AF%E5%81%8F%E7%A6%BB%22%5D%0A"})]),fallback:P(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"费雪方程两国各写一遍，实际利率差接实际汇率的预期变化（实际利率平价）。资产市场可以让 \\(E\\) 超调，物价粘住时 \\(q\\) 大幅摆动——那是蒙代尔短期，Dornbusch 超调是附录气质的对照，主干后课用 MF 处理流量 IS。",-1)),E[4]||(E[4]=a("h3",{id:"ppp-不是交易策略",tabindex:"-1"},[e("PPP 不是交易策略 "),a("a",{class:"header-anchor",href:"#ppp-不是交易策略","aria-label":'Permalink to "PPP 不是交易策略"'},"​")],-1)),E[5]||(E[5]=a("p",null,"一价在关税、配额、定价市场分割下失败。PPP 用 CPI 时含住房与服务，更失败于短期。本课禁止把「PPP 低估」写成必升值的预测菜单；卢卡斯批判对「用历史回归买卖外汇」同样适用。",-1)),E[6]||(E[6]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[7]||(E[7]=a("p",null,"若所有货物可贸易、价格灵活，货币扩张按数量论抬 \\(P\\)，为保持一价，\\(E\\) 同比例贬值，实际变量与 \\(CA\\) 的实物路径不变——开放经济的长期中性。短期 \\(P\\) 粘住，\\(E\\) 若被资产市场立刻推动，\\(q\\) 变动，支出在本国与外国货物间转换，\\(CA\\) 与 \\(Y\\) 可以动。这正是后课要把 IS 打开国境的原因。",-1)),E[8]||(E[8]=a("p",null,"同一次货币扩张，长期走中性、短期走实际波动：",-1)),(l(),p(t,null,{default:P(()=>[o(B,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E8%B4%A7%E5%B8%81%E6%89%A9%E5%BC%A0%22%5D%20--%3E%20L%5B%22%E9%95%BF%E6%9C%9F%EF%BC%9AP%20%E5%90%8C%E6%AF%94%E4%BE%8B%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20L%20--%3E%20N%5B%22E%20%E5%90%8C%E6%AF%94%E4%BE%8B%E8%B4%AC%E5%80%BC%EF%BC%9A%E4%B8%80%E4%BB%B7%E4%BF%9D%E6%8C%81%22%5D%0A%20%20N%20--%3E%20NEU%5B%22%E5%AE%9E%E9%99%85%E5%8F%98%E9%87%8F%E4%B8%8E%20CA%20%E4%B8%8D%E5%8F%98%EF%BC%9A%E9%95%BF%E6%9C%9F%E4%B8%AD%E6%80%A7%22%5D%0A%20%20M%20--%3E%20S%5B%22%E7%9F%AD%E6%9C%9F%EF%BC%9AP%20%E7%B2%98%E4%BD%8F%22%5D%0A%20%20S%20--%3E%20E%5B%22%E8%B5%84%E4%BA%A7%E5%B8%82%E5%9C%BA%E7%AB%8B%E5%88%BB%E6%8E%A8%E5%8A%A8%20E%20%E8%B4%AC%E5%80%BC%22%5D%0A%20%20E%20--%3E%20Q%5B%22%E5%AE%9E%E9%99%85%E6%B1%87%E7%8E%87%20q%20%E4%B8%8A%E5%8D%87%EF%BC%9A%E6%9C%AC%E5%9B%BD%E8%B4%A7%E7%9B%B8%E5%AF%B9%E5%8F%98%E4%BE%BF%E5%AE%9C%22%5D%0A%20%20Q%20--%3E%20R%5B%22%E6%94%AF%E5%87%BA%E8%BD%AC%E5%90%91%E6%9C%AC%E5%9B%BD%E8%B4%A7%EF%BC%9ACA%20%E4%B8%8E%20Y%20%E5%8F%98%E5%8A%A8%22%5D%0A"})]),fallback:P(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[9]||(E[9]=n('<p><span class="marginnote">直觉类比：一价定律像「同款手机全世界一个价」——纽约比东京便宜，代购就把差价磨平。PPP 把这句话推广到整个物价篮子；麻烦在于理发、房租这类不可贸易的服务没法代购，篮子里这类项目掺得越多，一价定律越使不上劲。</span></p><p>铸币税与通胀差：更高的稳态 \\(\\pi\\) 伴随更高的 \\(\\Delta\\ln E\\)，不是用贬值去「促进出口」的长期菜单。自然率仍在：汇率名义值不永久改变 \\(u^*\\)。</p><p>LOOP 是货物市场套利。CIP 是债券加远期的金融套利，见 <code>/quant/irp</code>。UIP 用期望即期替代远期，是风险溢价为零的假说，不在本课检验。宏观用 PPP 当物价锚；量化栏用报价与基差当事实。Balassa–Samuelson：可贸易生产率高的国家，不可贸易价格更高，\\(q\\) 可系统偏离绝对 PPP 而不违背 LOOP。</p><p><span class="marginnote">报价默认「一单位外币的本币价格」。相反报价只改口。用 CPI 检验 PPP 与用可贸易价格指数，答案不同。本课不把某个半衰期当定律。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在此写完整的汇率微观结构。不要把黄金输送点当现代 PPP。关税与不可贸易使 \\(q\\) 有趋势；发展核算里穷国物价更便宜，与巴拉萨–萨缪尔森一致，不是否定相对 PPP 作为通胀差的一阶故事。PPP 低估不是必升值的交易菜单。</p><p><span class="marginnote">常见误区：把「PPP 低估」当成「必升值」的信号下单。实证上偏差可以持续多年（收敛半衰期常以年计），篮子里又混着大量不可贸易品；PPP 是长期名义锚的参照，不是每季度的汇率预测菜单。</span></p><p>后课默认：长期 \\(\\Delta\\ln E\\) 对齐通胀差；短期 \\(q\\) 可大幅偏离。后课：资本流动与利率把 IS–LM 拉到开放。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>一价定律在货物层；PPP 是价格指数上的近似。</li><li>相对 PPP 把贬值接到通胀差，与两国数量论相容。</li><li>不可贸易与篮子使实际汇率可以长期不等于 1。</li><li>短期粘性下 \\(E\\) 可先动，\\(q\\) 驱动支出转换。</li><li>CIP/UIP 的市场内容在量化栏，本课不重导。</li><li>出处：Cassel 的 PPP；Friedman 对浮动汇率与货币的论述。</li></ul>',10))])}const h=i(A,[["render",d]]);export{f as __pageData,h as default};
